// Delete demands greedily. An eight-clique is an eight-row packing; a row missing nothing can repeat. Return a packing for every single-demand ablation.
use std::io::{self,Read};type Bits=Vec<u64>;
fn first(s:&Bits)->Option<usize>{s.iter().position(|&x|x!=0).map(|i|64*i+s[i].trailing_zeros()as usize)}
fn clique(adj:&[Bits],mut p:Bits,k:usize)->Option<Vec<usize>>{if k==0{return Some(vec![])}let mut rem=p.clone();let mut order=vec![];let mut col=0;while first(&rem).is_some(){col+=1;let mut cl=rem.clone();while let Some(i)=first(&cl){order.push((i,col));rem[i/64]&=!(1<<(i%64));cl[i/64]&=!(1<<(i%64));for j in 0..cl.len(){cl[j]&=!adj[i][j]}}}for(i,c)in order.into_iter().rev(){if c<k{break}let q=p.iter().zip(&adj[i]).map(|(a,b)|a&b).collect();if let Some(mut v)=clique(adj,q,k-1){v.push(i);return Some(v)}p[i/64]&=!(1<<(i%64))}None}
fn solve(miss:&[Bits],qs:&[usize],n:usize)->Option<Vec<usize>>{let w=(n+63)/64;let mut f=vec![u64::MAX;w];if n%64!=0{f[w-1]=(1u64<<(n%64))-1}let mut adj=vec![f.clone();n];for &k in qs{let m=&miss[k];for j in 0..w{let mut t=m[j];while t!=0{let i=64*j+t.trailing_zeros()as usize;t&=t-1;for u in 0..w{adj[i][u]&=!m[u]}}}}for i in 0..n{if adj[i][i/64]>>(i%64)&1!=0{return Some(vec![i;8])}}clique(&adj,f,8)}
fn main(){let mut s=String::new();io::stdin().read_to_string(&mut s).unwrap();let mut lines=s.lines().map(|l|l.split_whitespace().map(|v|v.parse::<u32>().unwrap()).collect::<Vec<_>>());let rows=lines.next().unwrap();let qs=lines.next().unwrap();let n=rows.len();let miss:Vec<_>=qs.iter().map(|q|{let mut b=vec![0;(n+63)/64];for(i,s)in rows.iter().enumerate(){if s&q==0{b[i/64]|=1<<(i%64)}}b}).collect();let mut core:Vec<_>=(0..qs.len()).collect();assert!(solve(&miss,&core,n).is_none());let mut order=core.clone();order.sort_by_key(|&i|miss[i].iter().map(|x|x.count_ones()).sum::<u32>());for i in order{let new=core.iter().copied().filter(|&j|i!=j).collect::<Vec<_>>();if solve(&miss,&new,n).is_none(){core=new}}println!("{:?}",core);for &i in &core{let new=core.iter().copied().filter(|&j|j!=i).collect::<Vec<_>>();println!("{:?}",solve(&miss,&new,n).unwrap())}}
